from functools import lru_cache
naive_calls=0
def naive(n):
    global naive_calls
    naive_calls+=1
    return n if n<2 else naive(n-1)+naive(n-2)
misses=0
@lru_cache(None)
def memo(n):
    global misses
    misses+=1
    return n if n<2 else memo(n-1)+memo(n-2)
naive(6)
memo(6)
print(naive_calls,misses)

